# Entité de la personne avec toutes ses sous-entités (hiérarchie Parent). Les droits plus larges
# (voir d'autres entités) se donnent dans les règles d'accès (🔐 Droits), pas ici.
vues = set()
a_voir = [$Entite] if $Entite else []
while a_voir:
    e = a_voir.pop()
    if e.id not in vues:
        vues.add(e.id)
        a_voir.extend(Gouv_Entites.lookupRecords(Parent=e.id))
return sorted(vues)
